'use strict';

// 统一结果合同：{ ok, data, error }。
// error 只含稳定错误码与脱敏信息，永不携带明文 Key、内部路径或完整签名 URL。

function ok(data = null) {
  return Object.freeze({ ok: true, data, error: null });
}

function fail(code, message) {
  if (typeof code !== 'string' || !code) {
    throw new TypeError('result.fail: code 必须是非空字符串');
  }
  return Object.freeze({
    ok: false,
    data: null,
    error: Object.freeze({ code, message: typeof message === 'string' ? message : '' })
  });
}

function isResult(value) {
  return !!value && typeof value === 'object' && typeof value.ok === 'boolean'
    && Object.prototype.hasOwnProperty.call(value, 'data')
    && Object.prototype.hasOwnProperty.call(value, 'error');
}

module.exports = { ok, fail, isResult };
